'use strict';
let renderer,revision=0,rings=[],cache=new Map(),cancelled=new Set();
const wrap=x=>((x%720)+720)%720;
function sample(fx,fy){const ny=Math.max(0,Math.min(359,Math.round(fy))),nx=wrap(Math.round(fx)),nearest=renderer.field[ny*720+nx];if(renderer.display==='grid'||!Number.isFinite(nearest))return nearest;const y=Math.max(0,Math.min(358,Math.floor(fy))),x=Math.floor(fx),dx=fx-x,dy=Math.max(0,Math.min(1,fy-y)),a=renderer.field[y*720+wrap(x)],b=renderer.field[y*720+wrap(x+1)],c=renderer.field[(y+1)*720+wrap(x)],d=renderer.field[(y+1)*720+wrap(x+1)];if(!Number.isFinite(a)||!Number.isFinite(b)||!Number.isFinite(c)||!Number.isFinite(d))return nearest;return a*(1-dx)*(1-dy)+b*dx*(1-dy)+c*(1-dx)*dy+d*dx*dy;}
function color(data,o,v,fx,fy){if(renderer.matchMask&&!renderer.matchMask[Math.max(0,Math.min(359,Math.round(fy)))*720+wrap(Math.round(fx))]){data[o+3]=0;return;}if(!Number.isFinite(v))data[o]=data[o+1]=data[o+2]=239;else{const q=Math.min(1,Math.max(0,v/renderer.high))*12,a=Math.min(11,Math.floor(q));for(let c=0;c<3;c++)data[o+c]=Math.floor(renderer.rgb[a][c]+(renderer.rgb[a+1][c]-renderer.rgb[a][c])*(q-a)+.5);}data[o+3]=255;}
function geometry(geo){rings=[];for(const f of geo.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const polygon of polygons)for(const ring of polygon){const points=new Float64Array(ring.length*2),bounds=[Infinity,Infinity,-Infinity,-Infinity];ring.forEach((p,i)=>{const lat=Math.max(-85.05112878,Math.min(85.05112878,p[1]))*Math.PI/180,x=(p[0]+180)/360,y=(1-Math.asinh(Math.tan(lat))/Math.PI)/2;points[i*2]=x;points[i*2+1]=y;bounds[0]=Math.min(bounds[0],x);bounds[1]=Math.min(bounds[1],y);bounds[2]=Math.max(bounds[2],x);bounds[3]=Math.max(bounds[3],y);});rings.push({points,bounds});}}}
async function tile(d){const key=[d.revision,d.z,d.x,d.y,d.ratio].join('/');let buffer=cache.get(key);if(!buffer){const n=2**d.z,cx=((d.x%n)+n)%n,scale=256*n,size=256*d.ratio,canvas=new OffscreenCanvas(size,size),ctx=canvas.getContext('2d'),texture=new OffscreenCanvas(size,size),tc=texture.getContext('2d'),im=tc.createImageData(size,size),fx=new Float64Array(size),fy=new Float64Array(size);for(let x=0;x<size;x++)fx[x]=((cx*256+(x+.5)/d.ratio)/scale*360-180-renderer.longitude)/.5;for(let y=0;y<size;y++)fy[y]=(renderer.latitude-Math.atan(Math.sinh(Math.PI*(1-2*(d.y*256+(y+.5)/d.ratio)/scale)))*180/Math.PI)/.5;for(let y=0;y<size;y++)for(let x=0;x<size;x++)color(im.data,(y*size+x)*4,sample(fx[x],fy[y]),fx[x],fy[y]);tc.putImageData(im,0,0);const path=new Path2D(),west=cx/n,east=(cx+1)/n,north=d.y/n,south=(d.y+1)/n;for(const {points,bounds:b} of rings){if(b[0]>east||b[2]<west||b[1]>south||b[3]<north)continue;for(let i=0;i<points.length;i+=2){const x=points[i]*scale-cx*256,y=points[i+1]*scale-d.y*256;if(i)path.lineTo(x,y);else path.moveTo(x,y);}path.closePath();}ctx.setTransform(d.ratio,0,0,d.ratio,0,0);ctx.clip(path);ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(texture,0,0);buffer=await (await canvas.convertToBlob({type:'image/png'})).arrayBuffer();if(d.revision===revision){cache.set(key,buffer);while(cache.size>64)cache.delete(cache.keys().next().value);}}
if(cancelled.delete(d.id))return;const copy=buffer.slice(0);postMessage({id:d.id,buffer:copy},[copy]);}
onmessage=({data:d})=>{if(d.type==='geometry')geometry(d.geo);else if(d.type==='field'){renderer=d;revision=d.revision;cache.clear();cancelled.clear();}else if(d.type==='cancel'){cancelled.add(d.id);if(cancelled.size>512)cancelled.delete(cancelled.values().next().value);}else if(d.type==='tile'){tile(d).catch(()=>postMessage({id:d.id,error:'Could not render climate tile'}));}};
